#[async_trait]
pub trait Tool: Send + Sync { /// The tool's registered name (used by the model to invoke it). fn name(&self) -> ToolName; /// Human-readable description shown to the model. fn description(&self) -> &str; /// JSON Schema object describing this tool's parameters. fn parameters_schema(&self) -> serde_json::Value; /// Risk classification, used by the approval policy. fn risk(&self) -> ToolRisk; /// Execute the tool. Check `cancel.is_cancelled()` at I/O boundaries. async fn execute( &self, arguments: serde_json::Value, cancel: CancellationToken, ) -> Result<ToolOutcome>;
}

